function renderQuiz(){const q=questions[quizIndex];$("#quizProgress").textContent="السؤال "+(quizIndex+1)+" من "+questions.length;$("#quizProgressBar").style.width=((quizIndex+1)/questions.length*100)+"%";$("#quizBody").innerHTML='<h2 class="quiz-question">'+safeText(q.q)+'</h2><div class="quiz-options">'+q.o.map((option,i)=>'<button class="quiz-option '+(quizAnswers[quizIndex]===i?"selected ":"")+(quizChecked&&i===q.a?"correct ":"")+(quizChecked&&quizAnswers[quizIndex]===i&&i!==q.a?"wrong":"")+'" data-answer="'+i+'" '+(quizChecked?"disabled":"")+'><span class="option-letter">'+String.fromCharCode(65+i)+'</span><span>'+safeText(option)+'</span></button>').join("")+'</div>'+(quizChecked?'<div class="quiz-feedback">'+(quizAnswers[quizIndex]===q.a?"✓ إجابة صحيحة. ":"✦ الإجابة الصحيحة: "+safeText(q.o[q.a])+". ")+safeText(q.e)+'</div>':"");$("#quizNext").textContent=quizIndex===questions.length-1?(quizChecked?"عرض النتيجة":"تحقق من الإجابة"):(quizChecked?"السؤال التالي ←":"تحقق من الإجابة ←");}
function answerQuiz(index){if(quizChecked)return;quizAnswers[quizIndex]=index;renderQuiz();}
function nextQuiz(){if(quizChecked&&quizIndex===questions.length-1){resetQuiz();return;}if(!quizChecked){if(quizAnswers[quizIndex]===undefined){showToast("اختر إجابة أولاً.");return;}quizChecked=true;renderQuiz();return;}if(quizIndex<questions.length-1){quizIndex++;quizChecked=false;renderQuiz();}else{const score=Math.round(quizAnswers.reduce((sum,a,i)=>sum+(a===questions[i].a?1:0),0)/questions.length*100);progress.quizzes++;progress.lastScore=score;store.set("progress",progress);renderProgress();$("#quizBody").innerHTML='<div class="empty-state"><span>✦</span><h2>أحسنت! نتيجتك '+score+'%</h2><p>أجبت إجابة صحيحة عن '+Math.round(score/100*questions.length)+' من '+questions.length+' أسئلة.</p></div>';$("#quizProgress").textContent="اكتمل الاختبار";$("#quizProgressBar").style.width="100%";$("#quizNext").textContent="اختبار جديد";}} 
function resetQuiz(){quizIndex=0;quizAnswers=[];quizChecked=false;renderQuiz();}
function renderFlashcard(){if(!cards.length){$("#flashText").textContent="لا توجد بطاقات بعد";$("#flashLabel").textContent="مجموعة فارغة";$("#flashHint").textContent="أضف أول بطاقة من النموذج";$("#flashCounter").textContent="0 / 0";return;}flashIndex=(flashIndex+cards.length)%cards.length;const card=cards[flashIndex];$("#flashCounter").textContent=(flashIndex+1)+" / "+cards.length;$("#flashcard").classList.toggle("flipped",flashFlipped);$("#flashLabel").textContent=flashFlipped?"الإجابة":"السؤال";$("#flashText").textContent=flashFlipped?card.a:card.q;$("#flashHint").textContent=flashFlipped?"اضغط لإظهار السؤال":"اضغط لإظهار الإجابة";}
